INSERT INTO zinas (virsraksts, teksts, kategorija, izveidots, publicets) VALUES
('3. diena — Valmiera un klusa jūra',
'Trešā diena aizsākās ar izbraucienu uz Valmieru. Pirmā pietura — dziju veikals pilsētas nomalē, no kura, protams, atkal grūti aiziet tukšām rokām. Pēc tam iepirkšanās, galvenokārt Depo — tādas praktiskas lietas, bez kurām ceļojums neiztiek.\n\nPēc pilsētas atkal uz jūru. Saule spīdēja, un vēja gandrīz nemaz nebija — ūdens gulēja gluds, spogulim līdzīgs, un smilšu mala vizēja gaismā. Reti kad rudens jūra ir tik klusa. Suņi mierīgi soļoja gar ūdens malu, bez steigas.\n\nVakarā atpakaļ mājiņā, kur kamīnā jau sprēgāja uguns. Silta istaba, klusums un liesmu spīdums — tāds vakars, pēc kura ilgojas visu gadu.\n\n⸻\n\nKolmas päivä alkoi ajelulla Valmieraan. Ensimmäinen pysähdys — lankakauppa laitakaupungilla, josta tietenkin taas on vaikea lähteä tyhjin käsin. Sen jälkeen kaupoilla käyntiä, lähinnä Depo — niitä käytännön tavaroita, joita ilman matka ei suju.\n\nKaupungin jälkeen taas rannalle. Aurinko paistoi, eikä tuullut juuri lainkaan — vesi lepäsi tyynenä ja peilimäisenä, ja hiekkakaistale kimalteli valossa. Harvoin syksyn meri on näin hiljainen. Koirat kävelivät rauhallisina veden äärellä, kiireettä.\n\nIllalla takaisin mökille, missä takassa jo rätisi tuli. Lämmin huone, hiljaisuus ja liekkien loiste — sellainen ilta, jota ikävöi pitkin vuotta.',
'celojums',
'2026-10-19 20:30:00',
1);
